custom_css:
/* 美化名字：漫画风*/
/*作者：hgu*/

/* ===== 核心控制台：在这里一键修改所有颜色 ===== */
:root {
  /* 颜色变量设定（默认黑白极简） */
  --气泡背景色: #ffffff;        /* 聊天气泡背景色 */
  --UI面板背景色: #ffffff;      /* 顶栏、底栏、侧边栏背景色 */
  --主题强调色: #000000;        /* 边框、图标、高亮、名字的颜色 */
  --主要文字色: #1a1a1a;        /* 正文聊天文字：深灰色 */
  --次要文字色: #888888;        /* 提示词、时间戳等次要信息 */

  /* 文案与字体设定 */
  --字体1: "Noto Sans SC";
  --自定义思维链文案: "​​君を愛してる...";
  --自定义“加载更多信息”文案: "✧ LOAD MORE MESSAGES ✧";
  --自定义输入框文字: "​​ずっといっしょにいたい";
}

/* 字体导入 */
@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;700;900&display=swap");

body {
  font-family: var(--字体1), sans-serif;
  color: var(--主要文字色);
}

/* === 一、全局 UI 面板（侧边栏、菜单） === */
.drawer-content, 
#table_drawer_content, 
.options-content {
  background-color: var(--UI面板背景色) !important;
  border-right: 2px solid var(--主题强调色) !important; 
  border-left: 2px solid var(--主题强调色) !important;
}


/* ===== 二、顶栏（黑白极简） ===== */
#top-settings-holder {
    background-color: var(--UI面板背景色);
    border: 2px solid var(--主题强调色);
    border-radius: 0px; /* 直角更有漫画分镜感 */
    box-shadow: 2px 2px 0px var(--主题强调色); 
}

#top-bar {
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
}

#top-settings-holder .drawer-icon::before {
  transition: transform 0.2s, color 0.2s;
  font-size: 17px;
  color: var(--主题强调色); 
}

#top-settings-holder .drawer-icon:hover::before {
    transform: scale(1.15);
}


/* ===== 三、底栏（黑白极简） ===== */
#send_form {
  background-color: var(--UI面板背景色);
  border-radius: 0px !important;
  border: 2px solid var(--主题强调色) !important;
  box-shadow: 4px 4px 0px var(--主题强调色); 
  padding: 0px 12px;
}

#send_textarea {
  border-radius: 0px !important;
  clip-path: none !important;
  background-color: transparent !important;
  border: 1px dashed var(--次要文字色) !important; 
  color: var(--主要文字色) !important;
}

#send_form [class*="fa-"]::before {
  font-size: 20px;
  color: var(--主题强调色);
  transition: transform 0.2s;
}

#send_form [class*="fa-"]:hover::before {
  transform: scale(1.15) rotate(5deg);
}


/* ===== 四、聊天区域 ===== */
#chat {
  background-color: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* （1）气泡整体布局 */
.mes {
    display: flex !important;
    flex-direction: column !important;
    width: 100%; 
    gap: 15px;
    margin-bottom: 30px !important;
}

/* （2）头像横幅 */
.mes .mesAvatarWrapper {
    position: relative !important; 
    width: 100% !important; 
    height:180px !important;
    aspect-ratio:10 / 7 !important; 

    background-image: url('https://pic1.imgdb.cn/item/69c4ebc82fb41b9ea32fcf6e.jpg');
    background-size: 100% 100% !important; 
    background-position: center !important;
    background-repeat: no-repeat !important;

    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    align-items: center !important;
    padding-top: 25.5% !important;    
    padding-bottom: 14% !important;   
    padding-left: 55% !important;     
    padding-right: 4% !important;     
    box-sizing: border-box !important;
    gap: 2px !important;

    border-radius: 0px; 
    box-shadow: 4px 4px 0px rgba(0,0,0,0.1);
}

/* （3）左侧区域：头像 + 头像框 */
.mes .avatar {
    position: absolute !important;
    top: 4% !important;
    left: 2.5% !important;
    width: 44% !important;
    height: 89% !important;
    margin: 0 !important;
    z-index: 1;
    overflow: visible !important; 
}
.mes .avatar img {
    width: 100% !important; 
    height: 100% !important; 
    border-radius: 2px !important; 
    object-fit: cover !important;
    border: none !important;
    box-shadow: none !important;
}
/* 头像框 */
.mes .avatar::after {
    content: '' !important;
    position: absolute !important;
    top: -4% !important;  
    left: -16% !important; 
    width: 228% !important; 
    height: 170% !important; 
    background-image: url('https://pic1.imgdb.cn/item/69c557f653701b6d63d9bf57.png') !important;
    background-size: 100% 100% !important; 
    background-position: center !important;
    background-repeat: no-repeat !important;
    pointer-events: none !important; 
    z-index: 5 !important; 
}

/* （4）三元素 */

.mes .mes_timer,
.mes .tokenCounterDisplay,
.mes .mesIDDisplay {
    opacity: 1 !important;          
    filter: none !important;         
    backdrop-filter: none !important;

    /*  背景与边框 */
    background-image: none !important; 
    background-color: #ffffff !important; 

    /* 3. 漫画风格外观 */
    position: relative !important;
    border: 2px solid #000000 !important; 
    color: #000000 !important; 

    /* 布局微调 */
    display: inline-block !important; 
    width: fit-content !important; 
    margin: 4px auto !important; 
    padding: 3px 8px !important; 
    font-weight: 900 !important;
    font-size: 16px !important; 
    text-align: center;
    border-radius: 0px !important; 
    box-shadow: 3px 3px 0px #000000 !important; 
    z-index: 99 !important; /* 确保它在最顶层 */
}

/* 隐藏原生图标 */
.mes .mes_timer i, .mes .tokenCounterDisplay i, .mes .mesIDDisplay i,
.mes .mes_timer svg, .mes .tokenCounterDisplay svg, .mes .mesIDDisplay svg {
    display: none !important;
}

/* 伪元素 */
.mes .mesIDDisplay::before { content: '第 ' !important; }
.mes .mesIDDisplay::after { content: ' 封情书' !important; }
.mes .mes_timer::before { content: '喜欢的第 ' !important; }
.mes .tokenCounterDisplay::before { content: '总计 ' !important; }

/* （5）下方区域：名字定位 */
/* 名字美化：白底黑框像素风 */
.mes .name_text {
    position: absolute !important;
    bottom: calc(100% + 14px) !important; 
    left: 38% !important; 

    background-color: #ffffff !important;  
    color: #000000 !important;           
    border: 3px solid #000000 !important; /* 黑框 */

    padding: 4px 15px !important;
    font-weight: 900 !important;
    font-size: 20px !important;
    z-index: 110 !important;              /* 确保在最顶层 */

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    white-space: nowrap !important;
}

/* （6）下方正文气泡） */
.mes .mes_block {
    position: relative !important; 
    overflow: visible !important; 

    background-color: var(--气泡背景色) !important; 
    border: 2px solid var(--主题强调色) !important; 
    color: var(--主要文字色) !important; /* 黑字 */

    border-radius: 0px; 
    padding: 15px 20px;
    box-shadow: 2px 2px 0px var(--主题强调色); 

    width: 100% !important;  
    box-sizing: border-box; 
}

.mes .mes_block .mes_text {
    border: 1px solid var(--主题强调色) !important; 
    padding: 15px !important;
    display: block !important;
    background: transparent !important;
}

.mes.last_mes .mesAvatarWrapper {
    margin-bottom: 0px !important; 
}

.mes .mes_text{
  padding: 0px;
  width: 100%;
}

          /*文本样式*/
/* 全局正文：字间距和行高 */
.mes_text {
    line-height: 1.8 !important;
    font-size: 14px !important;
}

/*心理文本*/
.mes_text em{
   border-bottom: 1px solid #000; 
}

/* 加粗文本  */
.mes_text strong {
    font-weight: 900 !important;
    color: #000 !important;
    text-shadow: 1px 1px 0px rgba(0,0,0,0.2) !important;
}

/* 4. 引用块 */
.mes_text q {
    border-left: 2px solid #000; !important;
    border-top: 1px solid #000; !important;
    border-bottom: 1px solid #000; !important;
    border-right: 1px solid #000; !important;
}

/* 5. 代码块  */
.mes_text code {
    background-color: #fff !important;
    border: 2px solid #000 !important;
    font-family: 'Courier New', Courier, monospace !important;
    padding: 2px 6px !important;
    box-shadow: 1px 1px 0px #000 !important; 
}


/* ===== 五、滚动条 + 滑动条（黑白极简） ===== */
::-webkit-scrollbar {
    width: 3px;
    height: 8px;
    background-color: transparent; 
}
::-webkit-scrollbar-track {
    background-color: transparent; 
    border-left: 1px dashed var(--次要文字色);
}
::-webkit-scrollbar-thumb {
    background-color: var(--主题强调色); 
    border-radius: 0px;
}

input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    background: transparent !important;
    cursor: pointer;
}
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 4px; 
    background: var(--主题强调色); 
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;    
    margin-top: -6px; 
    height: 16px; 
    width: 16px; 
    background-color: var(--气泡背景色);
    border: 2px solid var(--主题强调色); 
    border-radius: 0; 
    transition: transform 0.2s ease; 
}
input[type="range"]:hover::-webkit-slider-thumb {
    transform: scale(1.2) rotate(45deg); 
}


/* ===== 六、输入框提示文字 ===== */
#nonQRFormItems { position: relative; }
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--自定义输入框文字); 
    color: var(--次要文字色); 
    position: absolute; 
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%); 
    font-weight: bold;
    font-size: 13px;  
    pointer-events: none; 
    z-index: 10; 
}


/* ===== 七、正则 / 脚本 / 扩展（黑白块） ===== */
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}

.regex-script-label.flex-container,
.flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 8px 12px; 
  border-radius: 0px; 
  margin-bottom: 8px; 
  background: var(--UI面板背景色); 
  border: 2px solid var(--主题强调色); 
  box-shadow: 3px 3px 0px var(--主题强调色);
  color: var(--主要文字色);
}
.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
  flex-basis: 100%;
  font-weight: 900;
  font-size: 1.05em;
}


/* ===== 八、“加载更多消息”美化 ===== */
#show_more_messages {
  font-size: 0 !important;
  color: transparent !important; 
  display: block;
  padding: 10px 30px;
  margin: 25px auto; 
  width: fit-content; 

  background-color: var(--UI面板背景色); 
  border: 2px solid var(--主题强调色); 
  border-radius: 0px; 
  box-shadow: 4px 4px 0px var(--主题强调色); 
  cursor: pointer;
  transition: all 0.2s ease;
}
#show_more_messages::before {
  content: var(--自定义“加载更多信息”文案); 
  font-size: 14px !important; 
  font-weight: 900 !important;
  color: var(--主题强调色) !important; 
}
#show_more_messages:hover {
  background-color: var(--主题强调色); 
  transform: translate(-2px, -2px); 
  box-shadow: 6px 6px 0px var(--主题强调色);
}
#show_more_messages:hover::before {
  color: var(--UI面板背景色) !important; /* 悬停文字变白 */
}


/* ===== 九、思维链美化（黑白框） ===== */
.mes_reasoning_summary {
  list-style: none; 
  cursor: pointer;
  display: flex !important;
  align-items: center;
}
.mes_reasoning_header {
  background: transparent;
  border: 1px dashed var(--主题强调色); 
  border-radius: 0px; 
  padding: 6px 12px; 
  transition: all 0.2s ease-in-out;
}
.mes_reasoning_summary:hover .mes_reasoning_header {
  background: var(--ui面板背景色);
}
.mes_reasoning_header_title { font-size: 0 !important; }
.mes_reasoning_header_title::before {
  content: var(--自定义思维链文案); 
  font-size: 13px; 
  color: var(--主题强调色); 
  font-weight: bold; 
}
.mes_reasoning_arrow { font-size: 0 !important; }
.mes_reasoning_arrow::before {
  content: '▶'; 
  font-size: 12px; 
  color: var(--主题强调色);
  display: inline-block; 
  transition: transform 0.3s ease;
}
.mes_reasoning_summary:hover .mes_reasoning_arrow::before { color: var(--气泡背景色); }
details[open] .mes_reasoning_arrow::before { transform: rotate(90deg); }

.mes_reasoning {
  margin-top: 8px; 
  padding: 15px;
  background-color: transparent;
  border-left: 4px solid var(--主题强调色); 
  border-bottom: 1px dashed var(--次要文字色);
  color: var(--主要文字色); 
  font-size: 13px;
  line-height: 1.6; 
}

/* ===== 十、收藏栏滑动 ===== */
.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
  scrollbar-width: none;
}
.hotswap.avatars_inline::-webkit-scrollbar { display: none; }
@media (max-width: 768px) { .hotswap.avatars_inline { overflow: auto; } }


/* ===== 十一、补缺  ===== */

/* Toastr 提示条 */
#toast-container > div {
    background-color: #ffffff !important;
    border: 3px solid var(--主题强调色) !important;
    color: var(--主题强调色) !important;
    box-shadow: 5px 5px 0px var(--主题强调色) !important;
    border-radius: 0px !important;
    opacity: 1 !important;
}

/* 复选框适配 */
input[type="checkbox"] {
    appearance: none !important;
    width: 16px !important;
    height: 16px !important;
    border: 2px solid var(--主题强调色) !important;
    border-radius: 0px !important;
    background-color: #fff !important;
    position: relative !important;
    cursor: pointer;
}
input[type="checkbox"]:checked {
    background-color: var(--主题强调色) !important; 
}
input[type="checkbox"]:checked::before {
    content: "✕" !important;
    position: absolute !important;
    top: 50% !important; left: 50% !important;
    transform: translate(-50%, -50%) !important;
    color: #fff !important; font-size: 12px !important; font-weight: 900 !important;
}

/* 消息编辑状态 */
.mes_block textarea, .mes_edit_textarea {
    background-color: #ffffff !important;
    color: var(--主要文字色) !important;
    border: 2px dashed var(--主题强调色) !important;
    border-radius: 0px !important;
    padding: 10px !important;
}

/* 代码块 */
pre, code {
    background-color: #f8f8f8 !important;
    color: #000 !important;
    border: 1px solid var(--主题强调色) !important;
    border-radius: 0px !important;
    padding: 4px 8px !important;
}

/* 5. 通用输入框、下拉框 */
textarea:not(#send_textarea):not(.mes_edit_textarea):not(.mes_block textarea),
select, input[type="text"], input[type="number"] {
    background-color: #fff !important;
    color: var(--主要文字色) !important;
    border: 2px solid var(--主题强调色) !important;
    border-radius: 0px !important;
    padding: 8px 12px !important;
    transition: transform 0.1s !important;
}
select:focus, input:focus {
    transform: translate(-2px, -2px);
    box-shadow: 3px 3px 0px var(--主题强调色);
}

/* 6. 设置面板内的标题与分隔符 */
#user-settings-block h4,
#user-settings-block .inline-drawer-header,
#rm_extensions_block .inline-drawer-header {
    background: var(--主题强调色) !important;
    color: #fff !important;
    padding: 5px 10px !important;
    border-radius: 0px !important;
    font-weight: 900 !important;
    text-transform: uppercase;
    letter-spacing: 1px;
}

/* ===== 预设管理器条目：黑白直角漫画版 ===== */

/* 预设管理器列表总容器 */
#completion_prompt_manager_list {
    background-color: #ffffff !important;  
    color: #000000 !important;            
    border: 2px solid #000000 !important; 
    border-radius: 0px !important; /* 彻底直角 */
    padding: 10px !important;
    box-shadow: 4px 4px 0px #000000 !important; /* 漫画硬阴影 */
}

/* 列表内部的 li 项目（未选中状态） */
#completion_prompt_manager_list li {
    background-color: #ffffff !important;
    color: #000000 !important;
    border: 1px solid #000000 !important;
    border-radius: 0px !important; /* 彻底直角 */
    margin: 5px 0 !important;
    padding: 8px 12px !important;
    transition: all 0.1s ease !important;
    opacity: 1 !important;
}

/* 悬停效果 */
#completion_prompt_manager_list li:hover {
    background-color: #eeeeee !important; 
    border-color: #000000 !important;
    transform: translate(-1px, -1px);
    box-shadow: 2px 2px 0px #000000 !important;
}

/* 强制内部所有文字为黑色 */
#completion_prompt_manager_list *,
#completion_prompt_manager_list .completion_prompt_manager_prompt_name,
#completion_prompt_manager_list .prompt_manager_prompt_tokens,
#completion_prompt_manager_list .drag-handle {
    color: #000000 !important;
}

/* 被选中的条目（白底黑字+加粗边框/轻微底色） */
#completion_prompt_manager_list li.selected {
    background-color: #f2f2f2 !important; /* 极浅灰区分 */
    border: 3px solid #000000 !important; /* 边框加粗增强漫画感 */
    font-weight: 900 !important;
}

/* 所有 neo-range-input 类的元素（直角化） */
.neo-range-input {
    background-color: #ffffff !important;  
    color: #000000 !important;            
    border: 1px solid #000000 !important;
    border-radius: 0px !important; /* 彻底直角 */
    padding: 6px 10px !important;
    text-align: center !important;    
}

/* Total Tokens 统计部分 */
div:has(span[data-i18n="Total Tokens:"]) {
    color: #000000 !important;  
    font-weight: bold !important;
}
